blocks.text:
resolver 127.0.0.11 valid=5s ipv6=off;

# Кэш на диске контейнера: 10 МБ ключей в памяти (~80 000 ответов), до 200 МБ данных.
# Не запрашивался 10 минут — удаляется.
proxy_cache_path /var/cache/nginx/edge levels=1:2 keys_zone=edge:10m
                 max_size=200m inactive=10m use_temp_path=off;

upstream origin {
    zone origin 64k;
    server lb:80 resolve;
    keepalive 32;
}

server {
    listen 80;

    # Общие настройки проксирования для всех location
    proxy_http_version 1.1;
    proxy_set_header Connection "";
    proxy_set_header Host $host;
    proxy_set_header X-Real-IP $remote_addr;
    proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;

    # Каталог и статистика — одинаковые для всех пользователей, их кэшируем.
    location ~ ^/(products|stats)(/|$) {
        proxy_pass http://origin;

        proxy_cache edge;
        proxy_cache_key $request_method$request_uri;
        # «Микрокэш»: 10 секунд. Цена/остаток на витрине отстают максимум на 10 с,
        # зато популярный товар origin отдаёт 1 раз в 10 с, а не сотни раз
        proxy_cache_valid 200 10s;
        proxy_cache_valid 404 5s;

        # Пришло 100 запросов за одним и тем же устаревшим ответом —
        # к origin идёт только один, остальные ждут его (защита от «стада»)
        proxy_cache_lock on;
        proxy_cache_lock_timeout 2s;
        # Пока ответ обновляется в фоне или origin упал — отдаём устаревшую копию
        proxy_cache_use_stale error timeout updating http_500 http_502 http_503 http_504;
        proxy_cache_background_update on;

        # HIT / MISS / EXPIRED / STALE / UPDATING — видно в заголовках ответа
        add_header X-Cache-Status $upstream_cache_status always;
    }

    # Всё остальное (заказы, /health, /docs) — без кэша
    location / {
        proxy_pass http://origin;
    }
}
